import { test, expect } from '@playwright/test';

test.describe('File Upload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/upload');
  });

  test('should upload a file and confirm upload', async ({ page }) => {
    const filePath = 'path/to/your/small-text-file.txt'; // Update with the actual file path
    await page.getByLabel('File input').setInputFiles(filePath);
    await page.getByRole('button', { name: 'Upload' }).click();

    await expect(page.getByRole('heading', { name: 'File Uploaded!' })).toBeVisible();
    await expect(page.getById('uploaded-files')).toHaveText('small-text-file.txt'); // Update with the actual file name
  });

  test('should not upload a file if none is selected', async ({ page }) => {
    await page.getByRole('button', { name: 'Upload' }).click();

    await expect(page.getByRole('heading', { name: 'File Uploaded!' })).not.toBeVisible();
    await expect(page.getById('uploaded-files')).toHaveText('');
  });
});
